import React, { useEffect, useState } from "react";
import axios from "axios";
import Swal from "sweetalert2";
import "bootstrap/dist/css/bootstrap.min.css";
import "bootstrap/dist/js/bootstrap.bundle.min.js";
import "sweetalert2/dist/sweetalert2.min.css";
import './detalle_gestion.css';
import config from './config'; // Importa el archivo de configuración

const GestionForm = () => {
  const [gestionId, setGestionId] = useState(null);
  const [Id, setId] = useState(null);
  const [IdCampana, setIdCampana] = useState(null);

  const [formData, setFormData] = useState({
    NOMBRE: "",
    NIT: "",
    DPI: "",
    FECHA_NACIMIENTO: "",
    DIRECCION_CASA: "",
    DIRECCION_TRABAJO: "",
    LUGAR_TRABAJO: "",
    EMAIL: "",
    TELEFONO_CELULAR: "",
    TELEFONO_CASA: "",
    TELEFONO_ALTERNO: "",
    TELEFONO_TRABAJO: "",
    TIPO_CUENTA1: "",
    NO_CUENTA1: "",
    SALDO1: "",
    TIPO_CUENTA2: "",
    NO_CUENTA2: "",
    SALDO2: "",
    TIPO_CUENTA3: "",
    NO_CUENTA3: "",
    SALDO3: "",
    TIPO_CUENTA4: "",
    NO_CUENTA4: "",
    SALDO4: "",
    TIPO_CUENTA5: "",
    NO_CUENTA5: "",
    SALDO5: "",
    CONCEPTO1: "",
    DESCRIPCION1: "",
    CONCEPTO2: "",
    DESCRIPCION2: "",
    CONCEPTO3: "",
    DESCRIPCION3: "",
    CONCEPTO4: "",
    DESCRIPCION4: "",
  });

  const [movimientos, setMovimientos] = useState([]);

  /*const handleTokenError = () => {
    localStorage.removeItem("token");
    Swal.fire("Error", "No estás autenticado. Por favor, inicia sesión.", "error").then(() => {
      window.location.href = "/";
    });
  };*/

  const getToken = () => {
    const token = localStorage.getItem("token");
    
    if (!token) {
      Swal.fire({
        icon: 'error',
        title: 'Error',
        text: 'No estás autenticado. Por favor, inicia sesión.',
      }).then(() => {
        localStorage.removeItem('token'); 
        window.location.href = '/';
      });
      return; // Sale de la función para evitar continuar sin el token
    }
  
    return token;
  };
  
  const cargarMovimientos = async (gestionId) => {
    try {
      const token = getToken();
      const response = await axios.post(
        `${config.API_BASE_URL}/consulta-tipologias`,
        {
          id_gestion: gestionId, // Utiliza el id_gestion desencriptado
        },
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      console.log(response);
  
      if (response.data && Array.isArray(response.data)) {
        // Mapea los datos del endpoint para adaptarlos a la estructura de la tabla
        const movimientosAdaptados = response.data.map((movimiento) => ({
          tipoGestion: movimiento.TIPO_GESTION || "",
          subtipologia: movimiento.SUBTIPOLOGIA || "",
          tipologia: movimiento.TIPOLOGIA || "",
          razon_Mora: movimiento.RAZON_MORA || "",
          tipo_Contacto: movimiento.TIPO_CONTACTO || "",
          fecha: movimiento.FECHA || "",
          observaciones: movimiento.OBSERVACIONES || "",
          investigacion: movimiento.INVESTIGACION || "",
        }));
        setMovimientos(movimientosAdaptados);
      } else {
        setMovimientos([]);
      }
    } catch (error) {
      Swal.fire("Error", "No se pudieron cargar los movimientos.", "error");
      console.error(error);
    }
  };
  
  const decryptGestionId = async (encryptedValue) => {
    try {
      const token = getToken();
      const response = await axios.post(`${config.API_BASE_URL}/decrypt`, {
        encrypted_value: encryptedValue,
      }, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
      return response.data.decrypted_value;
    } catch (error) {
      Swal.fire({
        icon: "error",
        title: "Error de Desencriptado",
        text: "No se pudo desencriptar el valor.",
      });
      throw error;
    }
  };

  const cargarDatosFormulario = async (gestionId) => {
    try {
      const token = getToken();
      const response = await axios.post(`${config.API_BASE_URL}/gestiones`, {
        opcion: 4,
        id_gestiones: gestionId,
      }, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
      setFormData(response.data[0]);
    } catch (error) {
      Swal.fire("Error", "No se pudieron cargar los datos del formulario.", "error");
    }
  };

  const guardarCambios = async () => {
    try {
      // Validar que al menos uno de los campos telefónicos tenga un valor
      const { TELEFONO_CELULAR, TELEFONO_CASA, TELEFONO_ALTERNO, TELEFONO_TRABAJO, EMAIL } = formData;
  
      if (
        !TELEFONO_CELULAR &&
        !TELEFONO_CASA &&
        !TELEFONO_ALTERNO &&
        !TELEFONO_TRABAJO
      ) {
        Swal.fire("Error", "Debe ingresar al menos un número de teléfono.", "error");
        return;
      }

      // Desencriptar el gestionId (de forma correcta utilizando await)
      const GESTION_ID = await decryptGestionId(gestionId);
      
      if (!GESTION_ID) {
        Swal.fire("Error", "El ID de gestión no pudo ser desencriptado.", "error");
        return;
      }
      
      // Preparar el payload para el endpoint
      const payload = {
        id_gestion: GESTION_ID, // ID de gestión
        email: EMAIL,
        telefono1: TELEFONO_CELULAR || "",
        telefono2: TELEFONO_CASA || "",
        telefono3: TELEFONO_ALTERNO || "",
        telefono4: TELEFONO_TRABAJO || "",
      };
  
      const token = getToken();

      console.log(payload);
  
      // Consumir el endpoint
      const response = await axios.post(
        `${config.API_BASE_URL}/actualiza-informacion-contacto`,
        payload,
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );
  
    // Verificar si el código HTTP es 200
    if (response.status === 200) {
      Swal.fire("Éxito", "Información de contacto actualizada correctamente.", "success").then(() => {
        window.location.reload();
      });
    } else {
      Swal.fire("Error", "No se pudo guardar la información correctamente.", "error");
    }
    } catch (error) {
      Swal.fire("Error", "No se pudieron guardar los cambios.", "error");
      console.error(error);
    }
  };
  

  useEffect(() => {
    //cargarMovimientos();

    const urlParams = new URLSearchParams(window.location.search);
    const encryptedGestionId = urlParams.get("id_gestion");
    const encryptedId = urlParams.get("id");
    const encryptedCampana = urlParams.get("campana");
    setIdCampana(encryptedCampana);

    if (encryptedGestionId) {
      decryptGestionId(encryptedGestionId).then((gestionId) => {
        setGestionId(encryptedGestionId); // Guarda el ID en el estado
        cargarDatosFormulario(gestionId);
        cargarMovimientos(gestionId); // Carga los movimientos desde el endpoint
    });
    } else {
      Swal.fire("Error", "No se encontrarón los parametros necesarios.", "error");
    }

    if (encryptedId) {
        decryptGestionId(encryptedId).then((Id) => {
          setId(encryptedId); // Guarda el ID en el estado
    });

    } else {
      Swal.fire("Error", "No se encontrarón los parametros necesarios.", "error");
    }
    
  }, []);

  return (

    <div className="container mt-4">
    <div className="card">
      <div className="card-header text-center">
        <h3>Base clientes</h3>
      </div>
      <div className="card-body">
        <div className="d-flex justify-content-center mb-3">
        <button
          className="btn btn-success me-2"
          onClick={() => {
            if (gestionId) {
              window.location.href = `/registrar_gestion?id_gestion=${gestionId}&id=${Id}&campana=${IdCampana}`;
            } else {
              Swal.fire("Error", "ID de gestión no disponible.", "error");
            }
          }}
        >
          Agregar Gestión
        </button>

          <button className="btn btn-primary me-2" onClick={guardarCambios}>
            Guardar Cambios
          </button>

          <button
            className="btn btn-warning me-2"
            onClick={() => {
              if (gestionId) {
                window.location.href = `/registrar_pago?id_gestion=${gestionId}&id=${Id}`;
              } else {
                Swal.fire("Error", "ID de gestión no disponible.", "error");
              }
            }}
          >
            Registrar Pago
          </button>

          <button className="btn btn-secondary" onClick={() => window.history.back()}>Regresar</button>
        </div>

        <div className="accordion" id="gestionAccordion">
          {/* Información Deudor */}
          <div className="accordion-item">
            <h2 className="accordion-header" id="headingInfoDeudor">
              <button
                className="accordion-button"
                type="button"
                data-bs-toggle="collapse"
                data-bs-target="#collapseInfoDeudor"
                aria-expanded="true"
                aria-controls="collapseInfoDeudor"
              >
                Información Deudor
              </button>
            </h2>
            <div
              id="collapseInfoDeudor"
              className="accordion-collapse collapse show"
              aria-labelledby="headingInfoDeudor"
              data-bs-parent="#gestionAccordion"
            >
              <div className="accordion-body">
                <form id="gestionForm">
                  <div className="row">
                    <div className="col-md-6">
                      <div className="mb-3">
                        <label htmlFor="nombre" className="form-label">Nombre</label>
                        <input
                          type="text"
                          id="nombre"
                          className="form-control"
                          value={formData.NOMBRE || ''}
                          onChange={(e) => setFormData({ ...formData, NOMBRE: e.target.value })}
                          readOnly
                        />
                      </div>
                    </div>
                    <div className="col-md-6">
                      <div className="mb-3">
                        <label htmlFor="nit" className="form-label">NIT</label>
                        <input
                          type="text"
                          id="nit"
                          className="form-control"
                          value={formData.NIT || ''}
                          onChange={(e) => setFormData({ ...formData, NIT: e.target.value })}
                          readOnly
                        />
                      </div>
                    </div>
                    <div className="col-md-6">
                      <div className="mb-3">
                        <label htmlFor="dpi" className="form-label">DPI</label>
                        <input
                          type="text"
                          id="dpi"
                          className="form-control"
                          value={formData.DPI || ''}
                          onChange={(e) => setFormData({ ...formData, DPI: e.target.value })}
                          readOnly
                        />
                      </div>
                    </div>
                    <div className="col-md-6">
                      <div className="mb-3">
                        <label htmlFor="fechaNacimiento" className="form-label">Fecha de Nacimiento</label>
                        <input
                          type="date"
                          id="fechaNacimiento"
                          className="form-control"
                          value={formData.FECHA_NACIMIENTO || ''}
                          onChange={(e) => setFormData({ ...formData, FECHA_NACIMIENTO: e.target.value })}
                          readOnly
                        />
                      </div>
                    </div>
                    <div className="col-md-6">
                      <div className="mb-3">
                        <label htmlFor="direccionCasa" className="form-label">Dirección Casa</label>
                        <input
                          type="text"
                          id="direccionCasa"
                          className="form-control"
                          value={formData.DIRECCION_CASA || ''}
                          onChange={(e) => setFormData({ ...formData, DIRECCION_CASA: e.target.value })}
                          readOnly
                        />
                      </div>
                    </div>
                    <div className="col-md-6">
                      <div className="mb-3">
                        <label htmlFor="direccionTrabajo" className="form-label">Dirección Trabajo</label>
                        <input
                          type="text"
                          id="direccionTrabajo"
                          className="form-control"
                          value={formData.DIRECCION_TRABAJO || ''}
                          onChange={(e) => setFormData({ ...formData, DIRECCION_TRABAJO: e.target.value })}
                          readOnly
                        />
                      </div>
                    </div>
                    <div className="col-md-6">
                      <div className="mb-3">
                        <label htmlFor="lugarTrabajo" className="form-label">Lugar de Trabajo</label>
                        <input
                          type="text"
                          id="lugarTrabajo"
                          className="form-control"
                          value={formData.LUGAR_TRABAJO || ''}
                          onChange={(e) => setFormData({ ...formData, LUGAR_TRABAJO: e.target.value })}
                          readOnly
                        />
                      </div>
                    </div>
                    <div className="col-md-6">
                      <div className="mb-3">
                        <label htmlFor="email" className="form-label">Email</label>
                        <input
                          type="email"
                          id="email"
                          className="form-control"
                          value={formData.EMAIL || ''}
                          onChange={(e) => setFormData({ ...formData, EMAIL: e.target.value })}
                        />
                      </div>
                    </div>
                  </div>
                </form>
              </div>
            </div>
          </div>

          {/* Información de Contacto */}
          <div className="accordion-item">
            <h2 className="accordion-header" id="headingInfoContacto">
              <button
                className="accordion-button collapsed"
                type="button"
                data-bs-toggle="collapse"
                data-bs-target="#collapseInfoContacto"
                aria-expanded="false"
                aria-controls="collapseInfoContacto"
              >
                Información de Contacto
              </button>
            </h2>
            <div
              id="collapseInfoContacto"
              className="accordion-collapse collapse"
              aria-labelledby="headingInfoContacto"
              data-bs-parent="#gestionAccordion"
            >
              <div className="accordion-body">
                <div className="row">
                  <div className="col-md-6">
                    <div className="mb-3">
                      <label htmlFor="telefonoCelular" className="form-label">Teléfono Celular</label>
                      <input
                        type="number"
                        id="telefonoCelular"
                        className="form-control"
                        value={formData.TELEFONO_CELULAR || ''}
                        onChange={(e) => setFormData({ ...formData, TELEFONO_CELULAR: e.target.value })}
                      />
                    </div>
                  </div>
                  <div className="col-md-6">
                    <div className="mb-3">
                      <label htmlFor="telefonoCasa" className="form-label">Teléfono Casa</label>
                      <input
                        type="number"
                        id="telefonoCasa"
                        className="form-control"
                        value={formData.TELEFONO_CASA || ''}
                        onChange={(e) => setFormData({ ...formData, TELEFONO_CASA: e.target.value })}
                        
                      />
                    </div>
                  </div>
                  <div className="col-md-6">
                    <div className="mb-3">
                      <label htmlFor="telefonoAlterno" className="form-label">Teléfono Alterno</label>
                      <input
                        type="number"
                        id="telefonoAlterno"
                        className="form-control"
                        value={formData.TELEFONO_ALTERNO || ''}
                        onChange={(e) => setFormData({ ...formData, TELEFONO_ALTERNO: e.target.value })}
                        
                      />
                    </div>
                  </div>
                  <div className="col-md-6">
                    <div className="mb-3">
                      <label htmlFor="telefonoTrabajo" className="form-label">Teléfono Trabajo</label>
                      <input
                        type="number"
                        id="telefonoTrabajo"
                        className="form-control"
                        value={formData.TELEFONO_TRABAJO || ''}
                        onChange={(e) => setFormData({ ...formData, TELEFONO_TRABAJO: e.target.value })}
                        
                      />
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Conceptos y Descripciones */}
          <div className="accordion-item">
            <h2 className="accordion-header" id="headingConceptos">
              <button
                className="accordion-button collapsed"
                type="button"
                data-bs-toggle="collapse"
                data-bs-target="#collapseConceptos"
                aria-expanded="false"
                aria-controls="collapseConceptos"
              >
                Conceptos y Descripciones
              </button>
            </h2>
            <div
              id="collapseConceptos"
              className="accordion-collapse collapse"
              aria-labelledby="headingConceptos"
              data-bs-parent="#gestionAccordion"
            >
              <div className="accordion-body">
                <div className="row">
                  {Array.from({ length: 4 }).map((_, index) => (
                    <>
                      <div className="col-md-6" key={`concepto${index}`}>
                        <div className="mb-3">
                          <label htmlFor={`concepto${index + 1}`} className="form-label">Concepto {index + 1}</label>
                          <input
                            type="text"
                            id={`concepto${index + 1}`}
                            className="form-control"
                            value={formData[`CONCEPTO${index + 1}`] || ''}
                            onChange={(e) => setFormData({ ...formData, [`CONCEPTO${index + 1}`]: e.target.value })}
                            readOnly
                          />
                        </div>
                      </div>
                      <div className="col-md-6" key={`descripcion${index}`}>
                        <div className="mb-3">
                          <label htmlFor={`descripcion${index + 1}`} className="form-label">Descripción {index + 1}</label>
                          <textarea
                            id={`descripcion${index + 1}`}
                            className="form-control"
                            value={formData[`DESCRIPCION${index + 1}`] || ''}
                            onChange={(e) => setFormData({ ...formData, [`DESCRIPCION${index + 1}`]: e.target.value })}
                            readOnly
                          ></textarea>
                        </div>
                      </div>
                    </>
                  ))}
                </div>
              </div>
            </div>
          </div>

          {/* Tipologías */}
          <div className="accordion-item">
            <h2 className="accordion-header" id="headingTipologias">
              <button
                className="accordion-button collapsed"
                type="button"
                data-bs-toggle="collapse"
                data-bs-target="#collapseTipologias"
                aria-expanded="false"
                aria-controls="collapseTipologias"
              >
                Tipologías Registradas
              </button>
            </h2>
            <div
              id="collapseTipologias"
              className="accordion-collapse collapse"
              aria-labelledby="headingTipologias"
              data-bs-parent="#gestionAccordion"
            >
              <div className="accordion-body">
              <table className="table table-striped">
        <thead>
          <tr>
            <th>Tipo de Gestión</th>
            <th>Tipología</th>
            <th>Subtipología</th>
            <th>Razón de Mora</th>
            <th>Tipo de Contacto</th>
            <th>Observaciones</th>
            <th>Investigación</th>
            <th>Fecha</th>
          </tr>
        </thead>
        <tbody>
  {movimientos.length > 0 ? (
    movimientos.map((mov, index) => (
      <tr key={index}>
        <td>{mov.tipoGestion}</td>
        <td>{mov.tipologia}</td>
        <td>{mov.subtipologia}</td>
        <td>{mov.razon_Mora || "N/A"}</td>
        <td>{mov.tipo_Contacto || "N/A"}</td>
        <td>{mov.observaciones}</td>
        <td>{mov.investigacion}</td>
        <td>{mov.fecha || "N/A"}</td>
      </tr>
    ))
  ) : (
    <tr>
      <td colSpan="8" className="text-center">No hay tipologías registradas.</td>
    </tr>
  )}
</tbody>


      </table>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>

  );
};

export default GestionForm;
